#include "map_manager_ui.h"
#include "offline_map_coverage.h"
#include "offline_map.h"
#include "boat_state.h"
#include <math.h>
#include <stdio.h>
static lv_obj_t *page,*centreLabel,*estimateLabel,*packLabel,*coverageLabel,*progress;static lv_obj_t*zoomLabels[6];static float lat=43.0f,lon=25.0f;static bool chosen[6]={true,true,true,true,false,false};static uint8_t zlist[6]={14,15,16,17,18,19};static MapManagerReturnCallback onBack;
static lv_obj_t*label(lv_obj_t*p,const char*t,int x,int y,int w=750){lv_obj_t*l=lv_label_create(p);lv_label_set_text(l,t);lv_obj_set_pos(l,x,y);lv_obj_set_width(l,w);lv_label_set_long_mode(l,LV_LABEL_LONG_WRAP);return l;}
static void refresh(){char s[180];snprintf(s,sizeof(s),"Centre %.6f, %.6f | 1 km square",lat,lon);lv_label_set_text(centreLabel,s);uint8_t zs[6],n=0;uint32_t tiles=0;double dlat=500/111320.0,coslat=fabs(cos(lat*M_PI/180));if(coslat<1e-5)coslat=1e-5;double dlon=500/(111320.0*coslat);for(int i=0;i<6;i++){char z[12];snprintf(z,sizeof(z),"Z%u%s",zlist[i],chosen[i]?" *":"");lv_label_set_text(zoomLabels[i],z);if(chosen[i]){zs[n++]=zlist[i];double nn=1UL<<zlist[i];int x0=floor((lon-dlon+180)/360*nn),x1=floor((lon+dlon+180)/360*nn);double north=lat+dlat,south=lat-dlat;int y0=floor((1-asinh(tan(north*M_PI/180))/M_PI)/2*nn),y1=floor((1-asinh(tan(south*M_PI/180))/M_PI)/2*nn);tiles+=(x1-x0+1)*(abs(y1-y0)+1);}}
uint32_t bytes=tiles*131072UL;snprintf(s,sizeof(s),"Approx %lu tiles | %.2f MiB raw | %.2f MiB +10%%",(unsigned long)tiles,bytes/1048576.0,bytes*1.1/1048576.0);lv_label_set_text(estimateLabel,s);uint16_t total=0,ok=0,missing=0;offlineMap_getCoverageStats(total,ok,missing);snprintf(s,sizeof(s),"SD pack: %s | index %u planned / %u present / %u missing",offlineMap_hasMapData()?"VALID":"NOT VALID",total,ok,missing);lv_label_set_text(packLabel,s);uint16_t need=0,covered=0,miss=0;mapCoverage_checkSquare(lat,lon,1000,zs,n,need,covered,miss);snprintf(s,sizeof(s),"Coverage check: %u of %u | missing %u",covered,need,miss);lv_label_set_text(coverageLabel,s);lv_bar_set_value(progress,need?covered*100/need:0,LV_ANIM_OFF);}
static void nudgeLat(int d){lat=fmax(-85.0f,fmin(85.0f,lat+d*.001f));refresh();}static void nudgeLon(int d){lon+=d*.001f;if(lon>180)lon-=360;if(lon< -180)lon+=360;refresh();}
static void toggle(lv_event_t*e){int i=(intptr_t)lv_event_get_user_data(e);chosen[i]=!chosen[i];refresh();}
static void back(lv_event_t*e){if(lv_event_get_code(e)==LV_EVENT_CLICKED){lv_obj_del(page);if(onBack)onBack();}}
static void btn(lv_obj_t*p,const char*t,int x,int y,int w,lv_event_cb_t cb,void*ud=nullptr){lv_obj_t*b=lv_button_create(p);lv_obj_set_size(b,w,38);lv_obj_set_pos(b,x,y);lv_label_set_text(lv_label_create(b),t);lv_obj_center(lv_obj_get_child(b,0));lv_obj_add_event_cb(b,cb,LV_EVENT_CLICKED,ud);}
void mapManagerUI_open(lv_obj_t*parent,float gpsLat,float gpsLon,bool gpsValid,MapManagerReturnCallback cb){onBack=cb;lat=gpsValid?gpsLat:43.0f;lon=gpsValid?gpsLon:25.0f;page=lv_obj_create(parent);lv_obj_set_size(page,790,440);lv_obj_center(page);lv_obj_set_style_bg_color(page,lv_color_hex(0x101820),LV_PART_MAIN);lv_obj_set_style_pad_all(page,10,LV_PART_MAIN);label(page,"OFFLINE MAP MANAGER",8,4,400);centreLabel=label(page,"",8,38);label(page,"Coordinate adjustment ±0.001° (~111m latitude)",8,70);btn(page,"LAT +",8,100,80,[](lv_event_t*){nudgeLat(1);});btn(page,"LAT -",94,100,80,[](lv_event_t*){nudgeLat(-1);});btn(page,"LON -",180,100,80,[](lv_event_t*){nudgeLon(-1);});btn(page,"LON +",266,100,80,[](lv_event_t*){nudgeLon(1);});btn(page,"USE GPS CENTRE",354,100,150,[](lv_event_t*){if(boatState.gpsValid){lat=boatState.latitude;lon=boatState.longitude;refresh();}});label(page,"Zoom selection",8,151);for(int i=0;i<6;i++){lv_obj_t*b=lv_button_create(page);lv_obj_set_size(b,72,40);lv_obj_set_pos(b,8+i*80,176);zoomLabels[i]=lv_label_create(b);lv_obj_center(zoomLabels[i]);lv_obj_add_event_cb(b,toggle,LV_EVENT_CLICKED,(void*)(intptr_t)i);}estimateLabel=label(page,"Storage estimate",8,230);packLabel=label(page,"Pack status",8,267);coverageLabel=label(page,"Coverage",8,304);progress=lv_bar_create(page);lv_obj_set_size(progress,760,20);lv_obj_set_pos(progress,8,337);lv_bar_set_range(progress,0,100);label(page,"Progress is coverage verification (not a file-transfer/install operation yet).",8,361);btn(page,"BACK",665,390,100,back);refresh();}
